  "hint.explain.label": "\u89E3\u91CA\u6B64\u5DE5\u4F5C\u7C3F",
  "hint.explain.prompt": "\u901A\u8BFB\u6574\u4E2A\u5DE5\u4F5C\u7C3F\u2014\u2014\u6BCF\u4E2A\u5DE5\u4F5C\u8868\u3001\u7ED3\u6784\u3001\u516C\u5F0F\u548C\u547D\u540D\u533A\u57DF\u3002\u7136\u540E\u4E3A\u6B64\u5DE5\u4F5C\u7C3F\u7F16\u5199\u6E05\u6670\u7684\u603B\u89C8\u548C\u4F7F\u7528\u624B\u518C\u3002\n\u6DB5\u76D6\uFF1A\u5DE5\u4F5C\u7C3F\u7684\u7528\u9014\u3001\u7EC4\u7EC7\u65B9\u5F0F\u3001\u5DE5\u4F5C\u8868\u4E4B\u95F4\u7684\u903B\u8F91\u6D41\u7A0B\u3001\u8F93\u5165\u6570\u636E\u7684\u4F4D\u7F6E\u4EE5\u53CA\u8F93\u51FA\u7684\u63A8\u5BFC\u65B9\u5F0F\u3002\n\u5982\u679C\u662F\u6A21\u578B\uFF1A\u89E3\u91CA\u5173\u952E\u5047\u8BBE\uFF08\u4EE5\u53CA\u5728\u54EA\u91CC\u66F4\u6539\u5B83\u4EEC\uFF09\u3001\u8BA1\u7B97\u903B\u8F91\u4EE5\u53CA\u8F93\u51FA\u5982\u4F55\u4F9D\u8D56\u8F93\u5165\u3002\n\u5982\u679C\u662F\u6570\u636E\uFF1A\u89E3\u91CA\u6570\u636E\u4EE3\u8868\u4EC0\u4E48\u3001\u5173\u952E\u5B57\u6BB5\u3001\u4EFB\u4F55\u6D3E\u751F\u5217\u4EE5\u53CA\u503C\u5F97\u6CE8\u610F\u7684\u6A21\u5F0F\u6216\u7A7A\u7F3A\u3002\n\u50CF\u5199\u6587\u6863\u4E00\u6837\u7EC4\u7EC7\u4F60\u7684\u89E3\u91CA\u2014\u2014\u5148\u4ECE\u6458\u8981\u5F00\u59CB\uFF0C\u7136\u540E\u9010\u4E00\u8BF4\u660E\u6BCF\u4E2A\u5DE5\u4F5C\u8868\u7684\u4F5C\u7528\u3002",
  "hint.financial.label": "\u5EFA\u7ACB\u8D22\u52A1\u6A21\u578B",
  "hint.financial.prompt": "\u9996\u5148\u901A\u8BFB\u6574\u4E2A\u5DE5\u4F5C\u7C3F\u2014\u2014\u6BCF\u4E2A\u5DE5\u4F5C\u8868\u3001\u7ED3\u6784\u3001\u516C\u5F0F\u3001\u547D\u540D\u533A\u57DF\u4EE5\u53CA\u4EFB\u4F55\u73B0\u6709\u6570\u636E\u3002\u5BF9\u5DF2\u6709\u5185\u5BB9\u53CA\u5176\u7EC4\u7EC7\u65B9\u5F0F\u5F62\u6210\u6E05\u6670\u7684\u8BA4\u8BC6\u3002\n\u5982\u679C\u5DE5\u4F5C\u7C3F\u4E3A\u7A7A\u767D\u6216\u57FA\u672C\u4E3A\u7A7A\uFF1A\u8BE2\u95EE\u6211\u9700\u8981\u4EC0\u4E48\u6837\u7684\u8D22\u52A1\u6A21\u578B\u2014\u2014\u4F8B\u5982 DCF\u3001LBO\u3001\u4E09\u8868\u6A21\u578B\u3001\u9884\u7B97\u3001\u9884\u6D4B\u6216\u5BF9\u6BD4\u2014\u2014\u7136\u540E\u4ECE\u5047\u8BBE\u5F00\u59CB\u9010\u6B65\u6784\u5EFA\u3002\n\u5982\u679C\u6709\u90E8\u5206\u5B8C\u6210\u7684\u6A21\u578B\uFF1A\u89E3\u91CA\u5F53\u524D\u7ED3\u6784\u3001\u903B\u8F91\u6D41\u7A0B\u3001\u5173\u952E\u5047\u8BBE\u4EE5\u53CA\u7F3A\u5931\u6216\u4E0D\u5B8C\u6574\u7684\u5185\u5BB9\u3002\u4E3B\u52A8\u63D0\u51FA\u6269\u5C55\u6216\u5B8C\u6210\u5B83\u3002\n\u5982\u679C\u6709\u6570\u636E\u4F46\u6CA1\u6709\u6A21\u578B\uFF1A\u89E3\u91CA\u6570\u636E\u4EE3\u8868\u4EC0\u4E48\uFF0C\u5EFA\u8BAE\u53EF\u4EE5\u4ECE\u4E2D\u5EFA\u6A21\u7684\u5185\u5BB9\uFF0C\u5E76\u4E3B\u52A8\u63D0\u51FA\u6784\u5EFA\u3002",
  "hint.format.label": "\u683C\u5F0F\u5316\u6B64\u5DE5\u4F5C\u8868",
  "hint.format.prompt": "\u5BA1\u67E5\u6B64\u5DE5\u4F5C\u8868\u5E76\u6839\u636E\u4E0A\u4E0B\u6587\u63A8\u65AD\u6BCF\u4E2A\u5355\u5143\u683C\u7684\u6B63\u786E\u683C\u5F0F\uFF0C\u7136\u540E\u5E94\u7528\u683C\u5F0F\uFF0C\u5305\u62EC\uFF1A\n- \u6570\u5B57\u683C\u5F0F\uFF08\u8D27\u5E01\u3001\u767E\u5206\u6BD4\u3001\u65E5\u671F\u3001\u6574\u6570\u4E0E\u5C0F\u6570\uFF09\n- \u5B57\u4F53\u989C\u8272\u7F16\u7801\uFF08\u4F8B\u5982\u8F93\u5165\u9879\u7528\u84DD\u8272\uFF0C\u516C\u5F0F\u7528\u9ED1\u8272\uFF09\n- \u8F93\u5165\u9879\u3001\u8F93\u51FA\u9879\u548C\u6807\u9898\u7684\u5355\u5143\u683C\u6837\u5F0F\n- \u4E00\u81F4\u7684\u6807\u9898\u548C\u5206\u533A\u6807\u7B7E\n\u786E\u4FDD\u683C\u5F0F\u4E00\u81F4\uFF1A\u4F8B\u5982\uFF0C\u5982\u679C\u5217\u4E2D\u6240\u6709\u5176\u4ED6\u5355\u5143\u683C\u4F7F\u7528\u4E00\u4F4D\u5C0F\u6570\uFF0C\u5219\u5E94\u7528\u76F8\u540C\u8BBE\u7F6E\u3002\u5982\u679C\u67D0\u884C\u4E3A\u7C97\u4F53\u6216\u659C\u4F53\uFF0C\u5219\u6269\u5C55\u5230\u8BE5\u884C\u4E2D\u4EFB\u4F55\u672A\u683C\u5F0F\u5316\u7684\u5355\u5143\u683C\u3002\n\u683C\u5F0F\u5316\u540E\uFF0C\u91CD\u65B0\u8BFB\u53D6\u5DE5\u4F5C\u8868\u5E76\u9A8C\u8BC1\u4F60\u7684\u66F4\u6539\u662F\u5426\u6B63\u786E\u3002",
  "hint.quality.label": "\u8D28\u91CF\u68C0\u67E5\u6B64\u5DE5\u4F5C\u7C3F",
  "hint.quality.prompt": "\u5BA1\u67E5\u6B64\u5DE5\u4F5C\u7C3F\u5728\u903B\u8F91\u3001\u5047\u8BBE\u548C\u683C\u5F0F\u65B9\u9762\u7684\u9519\u8BEF\u548C\u95EE\u9898\uFF1A\n- \u903B\u8F91\uFF1A\u65AD\u88C2\u6216\u5FAA\u73AF\u5F15\u7528\u3001\u516C\u5F0F\u4E2D\u7684\u786C\u7F16\u7801\u6570\u5B57\u3001\u884C /\u5217\u95F4\u4E0D\u4E00\u81F4\u7684\u516C\u5F0F\u6A21\u5F0F\u3001\u5DE5\u4F5C\u8868\u4E4B\u95F4\u7F3A\u5931\u7684\u94FE\u63A5\u3001#REF \u6216 #VALUE \u9519\u8BEF\u3002\n- \u5047\u8BBE\uFF1A\u6807\u8BB0\u4EFB\u4F55\u5173\u952E\u5047\u8BBE\uFF08\u5982\u589E\u957F\u7387\u3001\u6298\u73B0\u7387\u3001\u5229\u6DA6\u7387\uFF09\u2014\u2014\u5B83\u4EEC\u5408\u7406\u5417\uFF1F\u662F\u5426\u6E05\u6670\u6807\u6CE8\u4E14\u6613\u4E8E\u627E\u5230\uFF0C\u8FD8\u662F\u57CB\u85CF\u5728\u516C\u5F0F\u4E2D\uFF1F\n- \u683C\u5F0F\uFF1A\u5217\u5185\u4E0D\u4E00\u81F4\u7684\u6570\u5B57\u683C\u5F0F\u3001\u7F3A\u5931\u6216\u9519\u4F4D\u7684\u6807\u9898\u3001\u672A\u6807\u6CE8\u7684\u8F93\u5165\u5355\u5143\u683C\u3001\u4E0D\u4E00\u81F4\u7684\u5C0F\u6570\u4F4D\u6570\u6216\u8D27\u5E01\u7B26\u53F7\u3001\u6253\u7834\u89C6\u89C9\u6A21\u5F0F\u7684\u884C /\u5217\u3002\n\u5C06\u4F60\u7684\u53D1\u73B0\u6309\u4E25\u91CD\u6027\u5206\u7EC4\uFF0C\u4F5C\u4E3A\u4F18\u5148\u7EA7\u5217\u8868\u603B\u7ED3\u3002",
